**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int ile = 0;
    while (plik >> liczba) {
        int kopia = liczba;
        bool ok = true;
        int bladCyfra = 0;
        int bladReszta = 0;
        while (kopia > 0) {
            int c = kopia % 10;
            if (c != 0 && liczba % c != 0) {
                ok = false;
                bladCyfra = c;
                bladReszta = liczba % c;
                break;
            }
            kopia /= 10;
        }
        if (ok) {
            cout << liczba << ": podzielna przez kazda niezerowa cyfre -> TAK" << endl;
            ile++;
        } else {
            cout << liczba << ": " << liczba << " % " << bladCyfra
                 << " = " << bladReszta << " -> NIE" << endl;
        }
    }
    cout << "Liczb podzielnych przez kazda niezerowa cyfre: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Dla kazdej liczby wyodrebniamy cyfry. Pomijamy 0 (bo dzielenie przez 0 jest niedozwolone). Dla kazdej niezerowej cyfry sprawdzamy, czy liczba jest przez nia podzielna. Jesli choc jedna cyfra nie dzieli liczby, wypisujemy ja jako kontrprzyklad.

